/// <reference types="@stdlib/types"/>

import empty = require( '@stdlib/ndarray/base/empty' );
import zeros = require( '@stdlib/ndarray/base/zeros' );
import findElement = require( './index' );

/**
* Predicate function.
*
* @param x - input value
* @returns result
*/
function predicate( x: any ): boolean {
	return Boolean( x );
}

// The function returns an number...
{
	const sh = [ 2, 2 ];
	const ord = 'row-major';

	findElement( zeros( 'float64', sh, ord ), predicate ); // $ExpectType number
	findElement( zeros( 'float64', sh, ord ), predicate, {} ); // $ExpectType number
	findElement( zeros( 'float32', sh, ord ), predicate ); // $ExpectType number
	findElement( zeros( 'float32', sh, ord ), predicate, {} ); // $ExpectType number
	findElement( zeros( 'complex64', sh, ord ), predicate ); // $ExpectType Complex64
	findElement( zeros( 'complex64', sh, ord ), predicate, {} ); // $ExpectType Complex64
	findElement( zeros( 'complex128', sh, ord ), predicate ); // $ExpectType Complex128
	findElement( zeros( 'complex128', sh, ord ), predicate, {} ); // $ExpectType Complex128
	findElement( zeros( 'int32', sh, ord ), predicate ); // $ExpectType number
	findElement( zeros( 'int32', sh, ord ), predicate, {} ); // $ExpectType number
	findElement( zeros( 'int16', sh, ord ), predicate ); // $ExpectType number
	findElement( zeros( 'int16', sh, ord ), predicate, {} ); // $ExpectType number
	findElement( zeros( 'int8', sh, ord ), predicate ); // $ExpectType number
	findElement( zeros( 'int8', sh, ord ), predicate, {} ); // $ExpectType number
	findElement( zeros( 'uint32', sh, ord ), predicate ); // $ExpectType number
	findElement( zeros( 'uint32', sh, ord ), predicate, {} ); // $ExpectType number
	findElement( zeros( 'uint16', sh, ord ), predicate ); // $ExpectType number
	findElement( zeros( 'uint16', sh, ord ), predicate, {} ); // $ExpectType number
	findElement( zeros( 'uint8', sh, ord ), predicate ); // $ExpectType number
	findElement( zeros( 'uint8', sh, ord ), predicate, {} ); // $ExpectType number
	findElement( zeros( 'uint8c', sh, ord ), predicate ); // $ExpectType number
	findElement( zeros( 'uint8c', sh, ord ), predicate, {} ); // $ExpectType number
	findElement( empty( 'bool', sh, ord ), predicate ); // $ExpectType boolean
	findElement( empty( 'bool', sh, ord ), predicate, {} ); // $ExpectType boolean
	findElement( zeros( 'generic', sh, ord ), predicate ); // $ExpectType number
	findElement( zeros( 'generic', sh, ord ), predicate, {} ); // $ExpectType number

	findElement( zeros( 'float64', sh, ord ), { 'order': ord }, predicate ); // $ExpectType number
	findElement( zeros( 'float64', sh, ord ), { 'order': ord }, predicate, {} ); // $ExpectType number
	findElement( zeros( 'float32', sh, ord ), { 'order': ord }, predicate ); // $ExpectType number
	findElement( zeros( 'float32', sh, ord ), { 'order': ord }, predicate, {} ); // $ExpectType number
	findElement( zeros( 'complex64', sh, ord ), { 'order': ord }, predicate ); // $ExpectType Complex64
	findElement( zeros( 'complex64', sh, ord ), { 'order': ord }, predicate, {} ); // $ExpectType Complex64
	findElement( zeros( 'complex128', sh, ord ), { 'order': ord }, predicate ); // $ExpectType Complex128
	findElement( zeros( 'complex128', sh, ord ), { 'order': ord }, predicate, {} ); // $ExpectType Complex128
	findElement( zeros( 'int32', sh, ord ), { 'order': ord }, predicate ); // $ExpectType number
	findElement( zeros( 'int32', sh, ord ), { 'order': ord }, predicate, {} ); // $ExpectType number
	findElement( zeros( 'int16', sh, ord ), { 'order': ord }, predicate ); // $ExpectType number
	findElement( zeros( 'int16', sh, ord ), { 'order': ord }, predicate, {} ); // $ExpectType number
	findElement( zeros( 'int8', sh, ord ), { 'order': ord }, predicate ); // $ExpectType number
	findElement( zeros( 'int8', sh, ord ), { 'order': ord }, predicate, {} ); // $ExpectType number
	findElement( zeros( 'uint32', sh, ord ), { 'order': ord }, predicate ); // $ExpectType number
	findElement( zeros( 'uint32', sh, ord ), { 'order': ord }, predicate, {} ); // $ExpectType number
	findElement( zeros( 'uint16', sh, ord ), { 'order': ord }, predicate ); // $ExpectType number
	findElement( zeros( 'uint16', sh, ord ), { 'order': ord }, predicate, {} ); // $ExpectType number
	findElement( zeros( 'uint8', sh, ord ), { 'order': ord }, predicate ); // $ExpectType number
	findElement( zeros( 'uint8', sh, ord ), { 'order': ord }, predicate, {} ); // $ExpectType number
	findElement( zeros( 'uint8c', sh, ord ), { 'order': ord }, predicate ); // $ExpectType number
	findElement( zeros( 'uint8c', sh, ord ), { 'order': ord }, predicate, {} ); // $ExpectType number
	findElement( empty( 'bool', sh, ord ), { 'order': ord }, predicate ); // $ExpectType boolean
	findElement( empty( 'bool', sh, ord ), { 'order': ord }, predicate, {} ); // $ExpectType boolean
	findElement( zeros( 'generic', sh, ord ), { 'order': ord }, predicate ); // $ExpectType number
	findElement( zeros( 'generic', sh, ord ), { 'order': ord }, predicate, {} ); // $ExpectType number
}

// The compiler throws an error if the function is provided a first argument which is not an ndarray...
{
	findElement( 5, predicate ); // $ExpectError
	findElement( true, predicate ); // $ExpectError
	findElement( false, predicate ); // $ExpectError
	findElement( null, predicate ); // $ExpectError
	findElement( undefined, predicate ); // $ExpectError
	findElement( {}, predicate ); // $ExpectError
	findElement( [ 1 ], predicate ); // $ExpectError
	findElement( ( x: number ): number => x, predicate ); // $ExpectError
}

// The compiler throws an error if the function is provided a callback which is not a function...
{
	const x = zeros( 'generic', [ 2, 2 ], 'row-major' );

	findElement( x, '5' ); // $ExpectError
	findElement( x, true ); // $ExpectError
	findElement( x, false ); // $ExpectError
	findElement( x, null ); // $ExpectError
	findElement( x, undefined ); // $ExpectError
	findElement( x, {} ); // $ExpectError
	findElement( x, [ 1 ] ); // $ExpectError
}

// The compiler throws an error if the function is provided an options argument which is not an object...
{
	const x = zeros( 'generic', [ 2, 2 ], 'row-major' );

	findElement( x, '10', predicate, {} ); // $ExpectError
	findElement( x, 10, predicate, {} ); // $ExpectError
	findElement( x, false, predicate, {} ); // $ExpectError
	findElement( x, true, predicate, {} ); // $ExpectError
	findElement( x, [], predicate, {} ); // $ExpectError
	findElement( x, ( x: number ): number => x, predicate, {} ); // $ExpectError
}

// The compiler throws an error if the function is provided an `order` option which is not a valid order...
{
	const x = zeros( 'generic', [ 2, 2 ], 'row-major' );

	findElement( x, { 'order': '10' }, predicate ); // $ExpectError
	findElement( x, { 'order': 10 }, predicate ); // $ExpectError
	findElement( x, { 'order': null }, predicate ); // $ExpectError
	findElement( x, { 'order': false }, predicate ); // $ExpectError
	findElement( x, { 'order': true }, predicate ); // $ExpectError
	findElement( x, { 'order': [] }, predicate ); // $ExpectError
	findElement( x, { 'order': {} }, predicate ); // $ExpectError
	findElement( x, { 'order': ( x: number ): number => x }, predicate ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	findElement(); // $ExpectError
	findElement( zeros( 'float64', [ 2, 2 ], 'row-major' ) ); // $ExpectError
	findElement( zeros( 'float64', [ 2, 2 ], 'row-major' ), {}, ( x: number ): number => x, {}, {} ); // $ExpectError
}
